<?php
// nearest populated place from the GeoNames tiles generated by build/gen-places.mjs

final class Places {
  private const TILE = 10;
  private const EARTH_RADIUS_KM = 6371.0;
  private static array $tiles = [];

  // ['name', 'country' (ISO 3166-1 alpha-2), 'distanceKm'] or null when nothing lies within $maxKm
  public static function nearest(float $lat, float $lon, float $maxKm = 30.0): ?array {
    $dLat = $maxKm / 111.0;
    $dLon = $maxKm / (111.0 * max(0.01, cos(deg2rad(min(89.0, abs($lat))))));
    $keys = [];
    foreach ([$lat - $dLat, $lat + $dLat] as $la) {
      foreach ([$lon - $dLon, $lon, $lon + $dLon] as $lo) {
        $la = max(-90.0, min(89.99999, $la));
        $lo = fmod(fmod($lo + 180.0, 360.0) + 360.0, 360.0);
        $keys[(int)floor(($la + 90) / self::TILE) . '-' . (int)floor($lo / self::TILE)] = true;
      }
    }

    $best = null;
    $bestKm = $maxKm;
    foreach (array_keys($keys) as $key) {
      foreach (self::tile($key) as [$name, $pLat, $pLon, $country]) {
        if (abs($pLat - $lat) > $dLat) {
          continue;
        }
        $km = self::distanceKm($lat, $lon, $pLat, $pLon);
        if ($km <= $bestKm) {
          $bestKm = $km;
          $best = ['name' => $name, 'country' => $country, 'distanceKm' => round($km, 1)];
        }
      }
    }
    return $best;
  }

  private static function distanceKm(float $lat1, float $lon1, float $lat2, float $lon2): float {
    $a = sin(deg2rad($lat2 - $lat1) / 2) ** 2
      + cos(deg2rad($lat1)) * cos(deg2rad($lat2)) * sin(deg2rad($lon2 - $lon1) / 2) ** 2;
    return 2 * self::EARTH_RADIUS_KM * asin(min(1.0, sqrt($a)));
  }

  private static function tile(string $key): array {
    if (!isset(self::$tiles[$key])) {
      $dir = defined('APP_DATA_DIR') ? APP_DATA_DIR : __DIR__ . '/../data';
      $file = $dir . '/places/' . $key . '.php';
      self::$tiles[$key] = is_file($file) ? require $file : [];
    }
    return self::$tiles[$key];
  }
}
